  -- Dating a pregnancy
  ('75000000-0000-4000-8000-000000000001', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'Dating a pregnancy',
   'Naegele''s rule, the weight-gain shortcut, fundal height and the visit schedule',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Four small calculations that turn up constantly, and none of them is hard once you have the rule. This note is arithmetic, not physiology — learn the rules and the marks are free."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Estimated date of delivery — Naegele's rule"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Take the "}, {"type": "text", "text": "first", "marks": [{"type": "bold"}]}, {"type": "text", "text": " day of the last menstrual period, add 7 days, subtract 3 months."}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "First day. Add seven. Back three months. The most common error is using the last day of the period, or subtracting before adding."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Weight gain"}]}, {"type": "lab_values", "attrs": {"title": "What she should have gained", "columns": [{"label": "Stage"}, {"label": "Gain"}], "rows": [["First trimester (12 weeks)", "about 1 lb per month — 3 lb total"], ["Second and third trimesters", "about 1 lb per week"], ["Whole pregnancy", "28 lb, plus or minus 3 (so 25-31 lb)"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "The long way works, but there is a shortcut that gets you there in one step: "}, {"type": "text", "text": "weeks of gestation minus 9", "marks": [{"type": "bold"}]}, {"type": "text", "text": " is roughly the expected gain in pounds."}]}, {"type": "lab_values", "attrs": {"title": "What the variance means", "columns": [{"label": "Off the expected figure by"}, {"label": "Do this"}], "rows": [["1-2 lb", "Nothing — within normal limits"], ["3 lb", "Assess her"], ["4 lb or more", "Trouble — biophysical profile on the fetus"]]}}, {"type": "embedded_questions", "attrs": {"id": "emb-n1-a", "title": "Check yourself: dating and weight", "item_ids": ["NCLEX_TUT_MCQ_00201", "NCLEX_TUT_MCQ_00202"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Fundal height"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Not palpable at all until about 12 weeks — midway between symphysis pubis and umbilicus."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "At the umbilicus by 20-22 weeks."}]}]}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Its value is that it tells you the trimester without a scan and without a history — useful in an unconscious client. A fundus much larger than the dates suggest can point to a molar pregnancy."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The prenatal visit schedule"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Monthly until 28 weeks"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Every two weeks from 28 to 36 weeks"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Weekly from 36 weeks until delivery, or week 42 — whichever comes first"}]}]}]}, {"type": "callout", "attrs": {"tone": "note"}, "content": [{"type": "text", "text": "At 42 weeks the pregnancy is not allowed to continue: induction or caesarean."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n1-b", "title": "Check yourself: fundal height and visits", "item_ids": ["NCLEX_TUT_TF_00201", "NCLEX_TUT_MCQ_00203"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['maternity', 'dating', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE'),
  -- Positive, probable, presumptive
  ('75000000-0000-4000-8000-000000000002', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'Positive, probable, presumptive',
   'The signs that prove a pregnancy — and the three-word trick for range questions',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The exam cares about one distinction here: which findings PROVE a pregnancy, and which merely suggest one. Everything else is a distractor."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Positive signs — only four"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fetal skeleton on x-ray"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fetus on ultrasound"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Fetal heart heard (Doppler)"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "The EXAMINER palpates fetal movement"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Note the fourth carefully. The examiner feeling movement is positive. The MOTHER feeling movement is not — that is quickening, and it is presumptive. The exam swaps these deliberately."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Everything else — a positive pregnancy test included — is probable or presumptive. hCG rises in other conditions, cancer among them."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Chadwick, Goodell, Hegar"}]}, {"type": "lab_values", "attrs": {"title": "In alphabetical order, travelling upward", "columns": [{"label": "Sign"}, {"label": "What softens or changes"}, {"label": "Where"}], "rows": [["Chadwick", "Bluish discoloration", "Vulva, vagina, cervix"], ["Goodell", "Softening", "Cervix"], ["Hegar", "Softening", "Lower uterine segment"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "C, G, H — alphabetical, and they climb the anatomy from outside in. Goodell, good and soft."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n2-a", "title": "Check yourself: which signs prove it", "item_ids": ["NCLEX_TUT_SATA_00201", "NCLEX_TUT_MCQ_00204"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The three-word trick for range questions"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Obstetric findings come as ranges, and the exam picks which end it wants using one word in the stem."}]}, {"type": "lab_values", "attrs": {"title": "Same range, three different answers", "columns": [{"label": "The stem says"}, {"label": "You want"}, {"label": "Fetal heart (8-12 wk)"}, {"label": "Quickening (16-20 wk)"}], "rows": [["When would she FIRST...", "the earliest", "8 weeks", "16 weeks"], ["When would she MOST LIKELY...", "the middle", "10 weeks", "18 weeks"], ["When should she have... BY", "the latest", "12 weeks", "20 weeks"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Find the word before you look at the options. First, most likely, by — earliest, middle, latest. It turns a memory question into a reading question."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n2-b", "title": "Check yourself: reading the range", "item_ids": ["NCLEX_TUT_MCQ_00205", "NCLEX_TUT_MCQ_00206"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['maternity', 'signs', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE'),
  -- The stages and phases of labour
  ('75000000-0000-4000-8000-000000000003', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'The stages and phases of labour',
   'What defines labour, how to time it, and the one emergency you act on before calling anyone',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Labour questions are mostly about knowing where the client is in a fixed sequence — and about one emergency where the order of your actions is the whole question."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What confirms labour"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Not the contractions. Not the ruptured membranes. "}, {"type": "text", "text": "Progressive cervical dilation and effacement", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — labour is defined by what the cervix does. Everything else accompanies it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The four stages"}]}, {"type": "lab_values", "attrs": {"title": "Where she is", "columns": [{"label": "Stage"}, {"label": "From"}, {"label": "To"}], "rows": [["First", "Onset of true labour", "Full dilation (10 cm)"], ["Second", "Full dilation", "Delivery of the baby"], ["Third", "Delivery of the baby", "Delivery of the placenta"], ["Fourth", "Delivery of the placenta", "1-4 hours postpartum — recovery"]]}}, {"type": "lab_values", "attrs": {"title": "The three phases of the first stage", "columns": [{"label": "Phase"}, {"label": "Dilation"}, {"label": "What she is like"}], "rows": [["Latent", "0-3 cm", "Talkative, sociable, excited"], ["Active", "4-7 cm", "Serious, inward, working"], ["Transition", "8-10 cm", "Irritable, nauseated, wants to give up"]]}}, {"type": "callout", "attrs": {"tone": "tip"}, "content": [{"type": "text", "text": "Behaviour dates the phase as reliably as the centimetres. A client who has stopped making conversation and snaps at you is in transition until proved otherwise."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n3-a", "title": "Check yourself: where is she", "item_ids": ["NCLEX_TUT_MCQ_00207", "NCLEX_TUT_MCQ_00208"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Timing contractions"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Frequency — "}, {"type": "text", "text": "beginning of one to the beginning of the next", "marks": [{"type": "bold"}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Duration — "}, {"type": "text", "text": "beginning to end of the same contraction", "marks": [{"type": "bold"}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Intensity — how hard the fundus feels at the peak, or the pressure reading if monitored internally"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Measuring from the END of one contraction to the start of the next gives the RESTING interval, not the frequency. Different number, wrong answer."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Prolapsed cord — act before you call"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The presenting part is compressing the cord and the fetus is losing its blood supply. This is the classic item where the correct answer is not 'notify the provider'."}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Relieve the pressure "}, {"type": "text", "text": "immediately", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — knee-chest or Trendelenburg, gloved hand holding the presenting part off the cord"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Oxygen by mask"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Call for help"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Prepare for immediate delivery, usually caesarean"}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Never attempt to push a prolapsed cord back in. And never leave the client to go and telephone — you keep your hand where it is and send someone else."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n3-b", "title": "Check yourself: timing and emergencies", "item_ids": ["NCLEX_TUT_SN_00201", "NCLEX_TUT_MCQ_00209"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['maternity', 'labour', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE'),
  -- Reading a fetal monitor strip
  ('75000000-0000-4000-8000-000000000004', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'Reading a fetal monitor strip',
   'VEAL CHOP, and what to do about each pattern',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "One mnemonic carries almost every fetal monitoring question on the exam. Learn it properly and this stops being a topic."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "VEAL CHOP"}]}, {"type": "lab_values", "attrs": {"title": "The pattern and its cause", "columns": [{"label": "V E A L — what you see"}, {"label": "C H O P — what causes it"}, {"label": "Worry?"}], "rows": [["Variable decelerations", "Cord compression", "Yes — reposition"], ["Early decelerations", "Head compression", "No — benign"], ["Accelerations", "OK — a well fetus", "No — reassuring"], ["Late decelerations", "Placental insufficiency", "Yes — the ominous one"]]}}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Read down the two columns together. V-C, E-H, A-O, L-P. The two you act on are Variable and Late; Early and Accelerations are left alone."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Telling early from late"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": ""}, {"type": "text", "text": "Early", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — mirrors the contraction. Starts when it starts, ends when it ends. Head compression during descent."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": ""}, {"type": "text", "text": "Late", "marks": [{"type": "bold"}]}, {"type": "text", "text": " — lags behind it. Starts after the contraction begins, recovers after it finishes. The placenta is failing to perfuse."}]}]}]}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "The distinction is TIMING, not depth. A shallow late deceleration is far more worrying than a deep early one."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n4-a", "title": "Check yourself: naming the pattern", "item_ids": ["NCLEX_TUT_MCQ_00210", "NCLEX_TUT_TF_00202"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "What to do about late decelerations"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Every action aims at getting more blood to the placenta:"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Turn her to the left side — takes the uterus off the vena cava"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "STOP the oxytocin if it is running — "}, {"type": "text", "text": "never increase it", "marks": [{"type": "bold"}]}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Oxygen by mask"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Increase the plain IV fluid"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Notify the provider"}]}]}]}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "'Increase the oxytocin' appears as a distractor in almost every version of this question. Stronger contractions mean less placental perfusion — it is the exact opposite of what the fetus needs."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n4-b", "title": "Check yourself: acting on the strip", "item_ids": ["NCLEX_TUT_SATA_00202"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['maternity', 'monitoring', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE'),
  -- Postpartum assessment
  ('75000000-0000-4000-8000-000000000005', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'Postpartum assessment',
   'Tone, height, position — and the three things the exam actually asks',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Postpartum questions reduce to three things, and the exam asks about them relentlessly: the fundus, the lochia, and the temperature."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "The fundus — three properties, in order"}]}, {"type": "lab_values", "attrs": {"title": "Check all three, every time", "columns": [{"label": "Property"}, {"label": "Normal"}, {"label": "Abnormal means"}], "rows": [["Tone", "Firm", "Boggy — atony, and haemorrhage risk"], ["Height", "At the umbilicus for 24 h, then down 1 finger-breadth a day", "Rising or staying high — bladder or atony"], ["Position", "Midline", "Deviated — almost always a full bladder"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "Tone and position together decide your action. Boggy and MIDLINE — massage it. Deviated to the side — empty the bladder first, because massage will not hold against a full bladder pushing it up."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n5-a", "title": "Check yourself: the fundus", "item_ids": ["NCLEX_TUT_MCQ_00211", "NCLEX_TUT_MCQ_00212"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Lochia"}]}, {"type": "lab_values", "attrs": {"title": "What it should look like", "columns": [{"label": "Stage"}, {"label": "Days"}, {"label": "Colour"}], "rows": [["Rubra", "1-3", "Red"], ["Serosa", "4-10", "Pinkish-brown"], ["Alba", "10+", "Yellowish-white"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "The quantity matters more than the colour. Saturating a perineal pad in an hour is heavy; saturating one in 15 minutes is haemorrhage."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Temperature"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "A temperature up to 38 °C in the first 24 hours is expected — dehydration and the work of labour."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Above 38 °C after the first 24 hours suggests infection and is reported."}]}]}]}, {"type": "callout", "attrs": {"tone": "memory"}, "content": [{"type": "text", "text": "Fundus, lochia, temperature. If you can only remember three postpartum things, remember those three — and for the fundus, three properties: tone, height, position."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n5-b", "title": "Check yourself: normal or not", "item_ids": ["NCLEX_TUT_SATA_00203"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['maternity', 'postpartum', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE'),
  -- The normal newborn — and what is not
  ('75000000-0000-4000-8000-000000000006', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
   'The normal newborn — and what is not',
   'Skin variations that need only reassurance, and the timings that make a finding pathological',
   $j${"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Most newborn questions test one judgement: is this finding normal, or does it need reporting? The dividing line is very often a clock."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Skin findings that are normal"}]}, {"type": "lab_values", "attrs": {"title": "Reassure and document", "columns": [{"label": "Finding"}, {"label": "What it is"}, {"label": "Course"}], "rows": [["Milia", "Blocked sebaceous glands — white pinpoints on nose and chin", "Resolve in weeks"], ["Mongolian spots", "Blue-grey pigmentation, usually lower back or buttocks", "Fade over years"], ["Erythema toxicum", "Blotchy red newborn rash", "Self-limiting, days"], ["Telangiectatic nevi", "'Stork bites' — flat pink marks, nape, eyelids", "Fade"], ["Acrocyanosis", "Blue hands and feet, pink trunk", "Normal for 24-48 h"]]}}, {"type": "callout", "attrs": {"tone": "warning"}, "content": [{"type": "text", "text": "Document Mongolian spots carefully at birth. They are entirely normal, but a later examiner who has not seen the record can mistake them for bruising."}]}, {"type": "callout", "attrs": {"tone": "note"}, "content": [{"type": "text", "text": "A PORT WINE STAIN is the exception in this list. It is permanent, does not fade, and is not something to reassure a parent will go away."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n6-a", "title": "Check yourself: normal or report it", "item_ids": ["NCLEX_TUT_SATA_00204"], "source": "TUTOR"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Jaundice — the clock decides"}]}, {"type": "lab_values", "attrs": {"title": "When it appeared", "columns": [{"label": "Onset"}, {"label": "Interpretation"}], "rows": [["Within the first 24 hours", "PATHOLOGICAL — usually blood-group incompatibility. Investigate."], ["After 24 hours, days 2-3", "Physiological — the common, expected kind"], ["Days 4-7 in a breastfed infant", "Breast-milk jaundice"]]}}, {"type": "callout", "attrs": {"tone": "critical"}, "content": [{"type": "text", "text": "First 24 hours means pathological. This single rule answers more newborn jaundice questions than any bilirubin value."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "APGAR"}]}, {"type": "lab_values", "attrs": {"title": "Scored at 1 and 5 minutes", "columns": [{"label": "Score"}, {"label": "Means"}, {"label": "Do"}], "rows": [["8-10", "Vigorous", "Routine care"], ["4-7", "Moderate distress", "Stimulate, oxygen, reassess"], ["0-3", "Severe distress", "Resuscitate immediately"]]}}, {"type": "paragraph", "content": [{"type": "text", "text": "Five components, each scored 0 to 2: heart rate, respiratory effort, muscle tone, reflex irritability, colour."}]}, {"type": "embedded_questions", "attrs": {"id": "emb-n6-b", "title": "Check yourself: jaundice and APGAR", "item_ids": ["NCLEX_TUT_MCQ_00213", "NCLEX_TUT_MCQ_00214"], "source": "TUTOR"}}]}$j$::jsonb,
   ARRAY['newborn', 'neonatal', 'high-yield']::text[], ARRAY['Health Promotion and Maintenance']::text[], TRUE, 'TUTOR_WIDE')
