-- NCLEX_TUT_MCQ_00205 .. NCLEX_TUT_MCQ_00209
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks, parent_note_id)
VALUES
  ('NCLEX_TUT_MCQ_00205', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse is asked at what gestation the fetal heart can FIRST be detected by Doppler. What is the best answer?',
   'The fetal heart is detectable between 8 and 12 weeks. ''First'' asks for the EARLIEST end of the range, ''most likely'' asks for the middle, and ''should be by'' asks for the latest.',
   $j${"options": [{"id": "A", "text": "8 weeks"}, {"id": "B", "text": "10 weeks"}, {"id": "C", "text": "12 weeks"}, {"id": "D", "text": "16 weeks"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct — 'first' means the earliest end of the range.", "B": "Incorrect — 10 weeks is the 'most likely' answer.", "C": "Incorrect — 12 weeks is the 'should be heard by' answer.", "D": "Incorrect — that is the quickening range."}}$j$::jsonb,
   'Maternity', 'Ranges of values', 'Hard',
   ARRAY['maternity', 'signs']::text[], 1, '75000000-0000-4000-8000-000000000002'),
  ('NCLEX_TUT_MCQ_00206', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'By what gestation should quickening have been felt?',
   'Quickening falls between 16 and 20 weeks. ''By'' asks for the LATEST end of the range, so 20 weeks.',
   $j${"options": [{"id": "A", "text": "16 weeks"}, {"id": "B", "text": "18 weeks"}, {"id": "C", "text": "20 weeks"}, {"id": "D", "text": "24 weeks"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — 16 weeks answers 'when would she first'.", "B": "Incorrect — 18 weeks answers 'when would she most likely'.", "C": "Correct — 'by' takes the latest end.", "D": "Incorrect — outside the range."}}$j$::jsonb,
   'Maternity', 'Ranges of values', 'Medium',
   ARRAY['maternity', 'signs']::text[], 1, '75000000-0000-4000-8000-000000000002'),
  ('NCLEX_TUT_MCQ_00207', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Which finding is the truest confirmation that a client is in true labour?',
   'Labour is defined by what the CERVIX does. Contractions, ruptured membranes and bloody show all accompany labour but none of them confirms it — only progressive change in the cervix does.',
   $j${"options": [{"id": "A", "text": "Contractions every five minutes"}, {"id": "B", "text": "Progressive cervical dilation and effacement"}, {"id": "C", "text": "Rupture of membranes"}, {"id": "D", "text": "Bloody show"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — Braxton Hicks can be regular without changing the cervix.", "B": "Correct — cervical change is the definition.", "C": "Incorrect — membranes can rupture before labour begins.", "D": "Incorrect — it suggests cervical change but does not demonstrate it."}}$j$::jsonb,
   'Maternity', 'True labour', 'Medium',
   ARRAY['maternity', 'labour']::text[], 1, '75000000-0000-4000-8000-000000000003'),
  ('NCLEX_TUT_MCQ_00208', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client is 6 cm dilated with contractions every 3 minutes lasting 60 seconds. Which phase of the first stage is she in?',
   'First stage runs to full dilation and has three phases: latent (0-3 cm), active (4-7 cm), transition (8-10 cm). At 6 cm she is active.',
   $j${"options": [{"id": "A", "text": "Latent"}, {"id": "B", "text": "Active"}, {"id": "C", "text": "Transition"}, {"id": "D", "text": "Second stage"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — latent is 0-3 cm.", "B": "Correct — active is 4-7 cm.", "C": "Incorrect — transition begins at 8 cm.", "D": "Incorrect — second stage begins at full dilation."}}$j$::jsonb,
   'Maternity', 'Stages and phases', 'Easy',
   ARRAY['maternity', 'labour']::text[], 1, '75000000-0000-4000-8000-000000000003'),
  ('NCLEX_TUT_SN_00201', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SELECT_N',
   'The nurse is timing contractions. Select the TWO statements that describe how frequency and duration are measured.',
   'Frequency is beginning-to-beginning. Duration is beginning-to-end of the SAME contraction. Measuring frequency from the end of one to the start of the next gives you the resting interval, which is a different number.',
   $j${"options": [{"id": "A", "text": "Frequency: from the start of one contraction to the start of the next"}, {"id": "B", "text": "Frequency: from the end of one contraction to the start of the next"}, {"id": "C", "text": "Duration: from the start of a contraction to the end of that same contraction"}, {"id": "D", "text": "Duration: from the peak of a contraction to its end"}, {"id": "E", "text": "Frequency: from the peak of one contraction to the peak of the next"}], "select_count": 2}$j$::jsonb,
   $j${"answers": ["A", "C"], "feedback": {"A": "Correct — beginning to beginning.", "B": "Incorrect — that is the resting interval.", "C": "Correct — beginning to end of one contraction.", "D": "Incorrect — duration starts at the beginning, not the peak.", "E": "Incorrect — peak to peak is not how frequency is defined."}}$j$::jsonb,
   'Maternity', 'Timing contractions', 'Medium',
   ARRAY['maternity', 'labour']::text[], 2, '75000000-0000-4000-8000-000000000003'),
  ('NCLEX_TUT_MCQ_00209', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'During a vaginal examination the nurse feels a pulsating cord in the vagina. What is the nurse''s FIRST action?',
   'Prolapsed cord is an obstetric emergency: the presenting part is compressing the cord and the fetus is losing its blood supply. Relieve the pressure FIRST — knee-chest or Trendelenburg, with a gloved hand holding the presenting part off the cord. Never attempt to replace the cord.',
   $j${"options": [{"id": "A", "text": "Call the provider"}, {"id": "B", "text": "Place the client in knee-chest position and hold the presenting part off the cord"}, {"id": "C", "text": "Attempt to reinsert the cord"}, {"id": "D", "text": "Administer oxygen by mask"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — necessary, but not before relieving the compression.", "B": "Correct — take the pressure off the cord immediately.", "C": "Incorrect — never reinsert a prolapsed cord.", "D": "Incorrect — oxygen helps, but it does not restore cord flow."}}$j$::jsonb,
   'Maternity', 'Complications', 'Hard',
   ARRAY['maternity', 'labour', 'emergency']::text[], 1, '75000000-0000-4000-8000-000000000003')
