-- NCLEX_TUT_MCQ_00210 .. NCLEX_TUT_SATA_00203
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks, parent_note_id)
VALUES
  ('NCLEX_TUT_MCQ_00210', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A fetal monitor shows decelerations that begin after the contraction starts and return to baseline after it ends. What do these indicate?',
   'VEAL CHOP. LATE decelerations mirror the contraction but lag behind it, and they mean Placental insufficiency — the fetus is not being perfused. Late decelerations are the ominous ones.',
   $j${"options": [{"id": "A", "text": "Head compression — benign"}, {"id": "B", "text": "Cord compression"}, {"id": "C", "text": "Uteroplacental insufficiency"}, {"id": "D", "text": "A normal variation"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — head compression gives EARLY decelerations.", "B": "Incorrect — cord compression gives VARIABLE decelerations.", "C": "Correct — late decelerations mean uteroplacental insufficiency.", "D": "Incorrect — late decelerations are never a normal variation."}}$j$::jsonb,
   'Maternity', 'Fetal monitoring', 'Medium',
   ARRAY['maternity', 'monitoring']::text[], 1, '75000000-0000-4000-8000-000000000004'),
  ('NCLEX_TUT_SATA_00202', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Late decelerations appear on the monitor. Which actions should the nurse take? Select all that apply.',
   'Late decelerations mean the placenta is not perfusing. Everything you do aims at more blood to the placenta: reposition left, oxygen, more fluid, stop anything reducing perfusion, and escalate. Oxytocin makes contractions stronger and perfusion worse — it is stopped, never increased.',
   $j${"options": [{"id": "A", "text": "Turn the client onto her left side"}, {"id": "B", "text": "Increase the oxytocin infusion"}, {"id": "C", "text": "Give oxygen by mask"}, {"id": "D", "text": "Increase the rate of the plain IV fluid"}, {"id": "E", "text": "Notify the provider"}, {"id": "F", "text": "Ask the client to hold her breath and push"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "D", "E"], "feedback": {"A": "Correct — left side takes the uterus off the vena cava.", "B": "Incorrect — oxytocin must be STOPPED. Increasing it worsens the problem.", "C": "Correct.", "D": "Correct — volume supports placental perfusion.", "E": "Correct.", "F": "Incorrect — pushing is not the response, and this is not second stage."}}$j$::jsonb,
   'Maternity', 'Fetal monitoring', 'Hard',
   ARRAY['maternity', 'monitoring']::text[], 4, '75000000-0000-4000-8000-000000000004'),
  ('NCLEX_TUT_TF_00202', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'TF',
   'Early decelerations require immediate intervention.',
   'Early decelerations come from head compression as the fetus descends. They mirror the contraction exactly and are benign — they need documenting, not treating.',
   $j${"options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — early decelerations are benign.", "B": "Correct — head compression, expected during descent."}}$j$::jsonb,
   'Maternity', 'Fetal monitoring', 'Easy',
   ARRAY['maternity', 'monitoring']::text[], 1, '75000000-0000-4000-8000-000000000004'),
  ('NCLEX_TUT_MCQ_00211', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Two hours after a vaginal delivery the nurse finds the fundus soft, above the umbilicus and displaced to the right. What should the nurse do FIRST?',
   'A fundus that is high AND deviated to the right is the classic picture of a full bladder pushing the uterus up and over. The bladder is why it cannot contract down, so emptying it is the first action — massage alone will not fix a displaced fundus.',
   $j${"options": [{"id": "A", "text": "Massage the fundus"}, {"id": "B", "text": "Ask the client to empty her bladder"}, {"id": "C", "text": "Notify the provider"}, {"id": "D", "text": "Start an oxytocin infusion"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — massage is right for a boggy MIDLINE fundus; deviation points at the bladder.", "B": "Correct — a full bladder displaces the uterus and prevents contraction.", "C": "Incorrect — there is a nursing action to take first.", "D": "Incorrect — not before the reversible cause is dealt with."}}$j$::jsonb,
   'Maternity', 'Postpartum', 'Hard',
   ARRAY['maternity', 'postpartum']::text[], 1, '75000000-0000-4000-8000-000000000005'),
  ('NCLEX_TUT_MCQ_00212', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Twenty-four hours after delivery, where should the nurse expect the fundus to be?',
   'The fundus sits at the umbilicus in the first 24 hours, then descends about one finger-breadth per day, becoming non-palpable by around day 10.',
   $j${"options": [{"id": "A", "text": "Two finger-breadths above the umbilicus"}, {"id": "B", "text": "At the level of the umbilicus"}, {"id": "C", "text": "Two finger-breadths below the umbilicus"}, {"id": "D", "text": "Not palpable"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — above the umbilicus at 24 hours suggests a full bladder or atony.", "B": "Correct.", "C": "Incorrect — that is about day 2.", "D": "Incorrect — that is around day 10."}}$j$::jsonb,
   'Maternity', 'Postpartum', 'Medium',
   ARRAY['maternity', 'postpartum']::text[], 1, '75000000-0000-4000-8000-000000000005'),
  ('NCLEX_TUT_SATA_00203', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which findings in the immediate postpartum period should the nurse treat as abnormal? Select all that apply.',
   'Saturating a pad within 15 minutes is haemorrhage. A temperature above 38 °C after the first 24 hours suggests infection. A deviated fundus means a full bladder. Lochia rubra on day 1, afterpains during feeding, and a fundus that firms with massage are all expected.',
   $j${"options": [{"id": "A", "text": "Saturating a perineal pad in 15 minutes"}, {"id": "B", "text": "Lochia rubra on day 1"}, {"id": "C", "text": "A boggy fundus that firms with massage"}, {"id": "D", "text": "Temperature 38.6 °C on day 2"}, {"id": "E", "text": "A fundus deviated to the right"}, {"id": "F", "text": "Afterpains while breastfeeding"}]}$j$::jsonb,
   $j${"answers": ["A", "D", "E"], "feedback": {"A": "Correct — that rate of loss is haemorrhage.", "B": "Incorrect — expected for the first 3 days.", "C": "Incorrect — it firmed. That is what massage is for.", "D": "Correct — fever after 24 hours suggests infection.", "E": "Correct — deviation means a full bladder.", "F": "Incorrect — oxytocin release during feeding causes afterpains. Expected."}}$j$::jsonb,
   'Maternity', 'Postpartum', 'Medium',
   ARRAY['maternity', 'postpartum']::text[], 3, '75000000-0000-4000-8000-000000000005')
