-- NCLEX_TUT_SATA_00204 .. NCLEX_TUT_SATA_00205
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks, parent_note_id)
VALUES
  ('NCLEX_TUT_SATA_00204', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which newborn findings are NORMAL variations requiring reassurance only? Select all that apply.',
   'Milia, Mongolian spots, erythema toxicum and stork bites are all normal and self-resolving. Jaundice in the FIRST 24 hours is pathological. A port wine stain is permanent and does not fade — not a variation to reassure about.',
   $j${"options": [{"id": "A", "text": "Milia across the nose"}, {"id": "B", "text": "Mongolian spots on the lower back"}, {"id": "C", "text": "Jaundice appearing in the first 24 hours"}, {"id": "D", "text": "Erythema toxicum"}, {"id": "E", "text": "Telangiectatic nevi (stork bites)"}, {"id": "F", "text": "A port wine stain"}]}$j$::jsonb,
   $j${"answers": ["A", "B", "D", "E"], "feedback": {"A": "Correct — blocked sebaceous glands, resolve on their own.", "B": "Correct — normal, and important to document so they are not mistaken for bruising.", "C": "Incorrect — jaundice in the first 24 hours is pathological.", "D": "Correct — newborn rash, self-limiting.", "E": "Correct — stork bites fade.", "F": "Incorrect — a port wine stain is permanent."}}$j$::jsonb,
   'Maternity', 'Newborn variations', 'Medium',
   ARRAY['newborn', 'neonatal']::text[], 4, '75000000-0000-4000-8000-000000000006'),
  ('NCLEX_TUT_MCQ_00213', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A newborn becomes jaundiced at 12 hours of age. How should the nurse interpret this?',
   'The clock is what matters. Jaundice within the first 24 hours is PATHOLOGICAL — most often haemolytic disease from blood-group incompatibility. Physiological jaundice appears after 24 hours, typically days 2 to 3.',
   $j${"options": [{"id": "A", "text": "Physiological jaundice — expected"}, {"id": "B", "text": "Pathological — requires investigation"}, {"id": "C", "text": "Breast-milk jaundice — reassure the mother"}, {"id": "D", "text": "Normal if the bilirubin is under 12 mg/dL"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — physiological jaundice appears after 24 hours.", "B": "Correct — under 24 hours is pathological until proven otherwise.", "C": "Incorrect — breast-milk jaundice appears much later, around days 4-7.", "D": "Incorrect — the timing decides this, not the number."}}$j$::jsonb,
   'Maternity', 'Hyperbilirubinaemia', 'Medium',
   ARRAY['newborn', 'neonatal']::text[], 1, '75000000-0000-4000-8000-000000000006'),
  ('NCLEX_TUT_MCQ_00214', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A newborn has an APGAR of 5 at one minute. What does this indicate?',
   'APGAR 8-10 is vigorous and needs routine care. 4-7 is moderate distress: stimulate, give oxygen, reassess. 0-3 needs immediate resuscitation.',
   $j${"options": [{"id": "A", "text": "No action needed — reassess at five minutes"}, {"id": "B", "text": "Moderate distress — stimulate and give oxygen"}, {"id": "C", "text": "Severe distress — begin resuscitation immediately"}, {"id": "D", "text": "The infant is vigorous and needs routine care"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — 5 needs intervention now, not just observation.", "B": "Correct — 4-7 is the moderate-distress band.", "C": "Incorrect — full resuscitation is for 0-3.", "D": "Incorrect — 8-10 is vigorous."}}$j$::jsonb,
   'Maternity', 'APGAR', 'Easy',
   ARRAY['newborn', 'neonatal']::text[], 1, '75000000-0000-4000-8000-000000000006'),
  ('NCLEX_TUT_MCQ_00215', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client''s last menstrual period began 3 September. What is her estimated date of delivery?',
   '3 September + 7 days = 10 September; minus 3 months = 10 June.',
   $j${"options": [{"id": "A", "text": "10 June"}, {"id": "B", "text": "3 June"}, {"id": "C", "text": "10 December"}, {"id": "D", "text": "27 May"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct.", "B": "Incorrect — the 7 days were not added.", "C": "Incorrect — 3 months added instead of subtracted.", "D": "Incorrect."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_MCQ_00216', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A client at 34 weeks'' gestation has gained 19 lb. What is the nurse''s interpretation?',
   '34 - 9 = 25 lb expected. She is 6 lb short, and 4 lb or more in either direction calls for a biophysical profile.',
   $j${"options": [{"id": "A", "text": "Within normal limits"}, {"id": "B", "text": "3 lb below expected — assess her"}, {"id": "C", "text": "6 lb below expected — biophysical profile indicated"}, {"id": "D", "text": "Above the expected gain"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — 6 lb out is well beyond the 1-2 lb band.", "B": "Incorrect — the shortfall is 6 lb, not 3.", "C": "Correct — 4 lb or more means a BPP.", "D": "Incorrect — she is below, not above."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Hard',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_SATA_00205', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which findings would the nurse document as PROBABLE rather than positive signs of pregnancy? Select all that apply.',
   'Probable signs are objective but explicable by something other than pregnancy. Only the fetus itself — heard, seen, or palpated by an examiner — is positive.',
   $j${"options": [{"id": "A", "text": "Positive serum hCG"}, {"id": "B", "text": "Goodell's sign"}, {"id": "C", "text": "Fetal heart on Doppler"}, {"id": "D", "text": "Hegar's sign"}, {"id": "E", "text": "Fetus seen on ultrasound"}, {"id": "F", "text": "Chadwick's sign"}]}$j$::jsonb,
   $j${"answers": ["A", "B", "D", "F"], "feedback": {"A": "Correct — hCG rises in other conditions.", "B": "Correct.", "C": "Incorrect — that is positive.", "D": "Correct.", "E": "Incorrect — that is positive.", "F": "Correct."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 4, NULL)
