-- NCLEX_TUT_MCQ_00217 .. NCLEX_TUT_MCQ_00221
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks, parent_note_id)
VALUES
  ('NCLEX_TUT_MCQ_00217', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A nurse is asked when a client would MOST LIKELY first feel quickening. What is the best answer?',
   'Quickening spans 16-20 weeks. ''Most likely'' takes the middle of the range.',
   $j${"options": [{"id": "A", "text": "16 weeks"}, {"id": "B", "text": "18 weeks"}, {"id": "C", "text": "20 weeks"}, {"id": "D", "text": "22 weeks"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — earliest.", "B": "Correct — the middle.", "C": "Incorrect — latest.", "D": "Incorrect — outside the range."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_MCQ_00218', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A labouring client is 9 cm dilated, irritable, and says she cannot continue. Which phase is she in?',
   'Transition is 8-10 cm, and the behaviour — irritability, nausea, wanting to give up — is as diagnostic as the centimetres.',
   $j${"options": [{"id": "A", "text": "Latent"}, {"id": "B", "text": "Active"}, {"id": "C", "text": "Transition"}, {"id": "D", "text": "Second stage"}]}$j$::jsonb,
   $j${"answer": "C", "feedback": {"A": "Incorrect — 0-3 cm.", "B": "Incorrect — 4-7 cm.", "C": "Correct.", "D": "Incorrect — second stage starts at full dilation."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Easy',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_MCQ_00219', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Membranes rupture and the nurse sees a loop of cord at the introitus. What is the priority action?',
   'Relieve the compression first — everything else follows. The cord is covered with a MOIST sterile dressing, not a dry one, and delivery is usually caesarean.',
   $j${"options": [{"id": "A", "text": "Notify the provider"}, {"id": "B", "text": "Position knee-chest and lift the presenting part off the cord"}, {"id": "C", "text": "Cover the cord with a dry sterile dressing"}, {"id": "D", "text": "Prepare for immediate vaginal delivery"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — necessary, but not first.", "B": "Correct.", "C": "Incorrect — moist, not dry, and not before relieving pressure.", "D": "Incorrect — this is a caesarean, and not the first action."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Hard',
   ARRAY['maternity', 'mock', 'emergency']::text[], 1, NULL),
  ('NCLEX_TUT_MCQ_00220', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'The monitor shows decelerations that begin and end with each contraction, mirroring it exactly. What should the nurse do?',
   'Mirroring the contraction exactly means EARLY decelerations — head compression during descent. Benign; document them.',
   $j${"options": [{"id": "A", "text": "Document — this is expected"}, {"id": "B", "text": "Turn the client to her left side"}, {"id": "C", "text": "Stop the oxytocin"}, {"id": "D", "text": "Prepare for immediate delivery"}]}$j$::jsonb,
   $j${"answer": "A", "feedback": {"A": "Correct — early decelerations are benign.", "B": "Incorrect — that is the response to late or variable.", "C": "Incorrect — no need with early decelerations.", "D": "Incorrect."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_SN_00202', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SELECT_N',
   'Late decelerations are seen. Select the TWO actions the nurse should take FIRST.',
   'Left lateral position and oxygen are the two immediate perfusion measures. Oxytocin is stopped, never increased.',
   $j${"options": [{"id": "A", "text": "Increase the oxytocin"}, {"id": "B", "text": "Turn the client to her left side"}, {"id": "C", "text": "Give oxygen by mask"}, {"id": "D", "text": "Document and continue to observe"}, {"id": "E", "text": "Ask the client to push with the next contraction"}], "select_count": 2}$j$::jsonb,
   $j${"answers": ["B", "C"], "feedback": {"A": "Incorrect — stronger contractions worsen perfusion.", "B": "Correct.", "C": "Correct.", "D": "Incorrect — late decelerations are never watch-and-wait.", "E": "Incorrect."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Hard',
   ARRAY['maternity', 'mock']::text[], 2, NULL),
  ('NCLEX_TUT_MCQ_00221', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'Four hours postpartum the fundus is boggy and midline. What should the nurse do first?',
   'Boggy and MIDLINE means atony — massage it. Boggy and DEVIATED means a full bladder, and then voiding comes first.',
   $j${"options": [{"id": "A", "text": "Ask the client to void"}, {"id": "B", "text": "Massage the fundus"}, {"id": "C", "text": "Notify the provider"}, {"id": "D", "text": "Increase the IV rate"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — that is the answer when the fundus is deviated.", "B": "Correct.", "C": "Incorrect — massage first.", "D": "Incorrect."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 1, NULL)
