-- NCLEX_TUT_TF_00203 .. NCLEX_TUT_MCQ_00222
INSERT INTO nclex_tutor_questions
  (item_id, tutor_id, question_type, stem, rationale, content, correct,
   topic, subtopic, difficulty, tags, marks, parent_note_id)
VALUES
  ('NCLEX_TUT_TF_00203', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'TF',
   'A temperature of 37.9 °C in the first 24 hours after delivery should be reported as probable infection.',
   'Up to 38 °C in the first 24 hours is expected — dehydration and the work of labour. Above 38 °C AFTER the first 24 hours suggests infection.',
   $j${"options": [{"id": "A", "text": "True"}, {"id": "B", "text": "False"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — this is within the expected range for the first day.", "B": "Correct."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Medium',
   ARRAY['maternity', 'mock']::text[], 1, NULL),
  ('NCLEX_TUT_SATA_00206', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'SATA',
   'Which newborn findings require the nurse to notify the provider? Select all that apply.',
   'Jaundice inside 24 hours is pathological, an APGAR of 0-3 needs immediate resuscitation, and a rate of 78 is tachypnoeic (normal 30-60). Mongolian spots, acrocyanosis in the first 48 hours, and milia are all normal.',
   $j${"options": [{"id": "A", "text": "Jaundice at 10 hours of age"}, {"id": "B", "text": "Mongolian spots"}, {"id": "C", "text": "APGAR of 3 at one minute"}, {"id": "D", "text": "Acrocyanosis at 2 hours"}, {"id": "E", "text": "Milia"}, {"id": "F", "text": "A respiratory rate of 78 at 4 hours"}]}$j$::jsonb,
   $j${"answers": ["A", "C", "F"], "feedback": {"A": "Correct — pathological inside 24 hours.", "B": "Incorrect — normal.", "C": "Correct — resuscitate.", "D": "Incorrect — normal for 24-48 hours.", "E": "Incorrect — normal.", "F": "Correct — normal newborn rate is 30-60."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Hard',
   ARRAY['newborn', 'mock']::text[], 3, NULL),
  ('NCLEX_TUT_MCQ_00222', '4ed777d7-e4f7-403b-88f4-63ce5432d65e', 'MCQ',
   'A newborn is jaundiced on day 3. The nurse should recognise this as:',
   'After 24 hours, typically days 2-3, is physiological jaundice — the common and expected kind.',
   $j${"options": [{"id": "A", "text": "Pathological — investigate"}, {"id": "B", "text": "Physiological — expected"}, {"id": "C", "text": "Breast-milk jaundice"}, {"id": "D", "text": "A sign of sepsis"}]}$j$::jsonb,
   $j${"answer": "B", "feedback": {"A": "Incorrect — that is jaundice inside 24 hours.", "B": "Correct.", "C": "Incorrect — that appears days 4-7.", "D": "Incorrect — nothing here points to sepsis."}}$j$::jsonb,
   'Maternity', 'Mixed', 'Easy',
   ARRAY['newborn', 'mock']::text[], 1, NULL)
