) VALUES (
  '80000000-0000-4000-8000-000000000002', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Maternity & Newborn — Mock Exam',
  'One timed mock across the whole maternity section. Thirty minutes, no going back.',
  'A single timed mock, sat under exam conditions: sequential, no going back, thirty minutes for twelve items spanning dating, signs of pregnancy, labour, fetal monitoring, postpartum and the newborn.

There is no teaching here — it is an assessment. Every item carries a full rationale, so you will know exactly why each answer was what it was, but if you want the material taught first, buy the revision notes or the full course.

Unlimited re-sits.',
  'SELF_PACED', 'MODULE', 1,
  'GHS', TRUE, 'ON_PLATFORM',
  180, TRUE, 'PUBLISHED', NOW()
)
