) VALUES (
  '80000000-0000-4000-8000-000000000003', '4ed777d7-e4f7-403b-88f4-63ce5432d65e',
  'Maternity & Newborn — Learn by Doing',
  'The same six notes, but you answer as you read — then sit the mock.',
  'The complete maternity section, built so that you are answering questions within a minute of starting to read. Every note is broken up by practice checkpoints: read a rule, use it immediately, see the rationale, carry on.

That is the whole design. Reading a note about late decelerations teaches you less than being asked what to do about one and getting it wrong while the explanation is still in front of you.

Six notes covering pregnancy dating, the signs of pregnancy, labour, fetal monitoring, postpartum assessment and the newborn — then a timed mock across all six to prove it stuck.

Self-paced, no fixed dates. Twelve months'' access.',
  'SELF_PACED', 'MODULE', 7,
  'GHS', TRUE, 'ON_PLATFORM',
  365, TRUE, 'PUBLISHED', NOW()
)
